//https://leetcode.com/problems/pairs-of-songs-with-total-durations-divisible-by-60/

class Solution {
public:
    int numPairsDivisibleBy60(vector<int>& time) {
        unordered_map<int, int> m;
        int res = 0;
        for(auto t: time){
            int reminder = t % 60;
            int other = (60 - reminder)%60;

            res += m[other];
            m[reminder]++;
        }
        return res;
    }
};



class Solution {
public:
    int numPairsDivisibleBy60(vector<int>& time) {
        unordered_map<int, int> m;
        for(auto t: time){
            m[t]++;
        }
        vector<int> v;
        int val = 60;

        while(val < 1100){
            v.push_back(val);
            val += 60;
        }

        long long res = 0;
        for(auto t: time){
            for(auto val: v){
                if(m.count(val - t)){
                    if(t == val - t){
                        res += m[t] - 1;
                    }else{
                        res += m[val - t];
                    }
                }
            }
        }
        res = res / 2;
        return (int)res;
    }
};


